{
  "name": "opencode-mem0-bridge",
  "version": "0.0.0",
  "private": true,
  "repository": "github:mdc-git/opencode-mem0-bridge",
  "type": "module",
  "exports": {
    ".": "./plugins/mem0-bridge/index.ts"
  },
  "sideEffects": false,
  "engines": {
    "node": ">=24"
  },
  "scripts": {
    "check": "failed=0; node tooling/update-direct-deps.mjs || failed=1; prettier . --check --config tooling/prettier.json --ignore-path tooling/prettierignore || failed=1; eslint . --config tooling/eslint.config.js || failed=1; tsc --project tooling/tsconfig.json --noEmit || failed=1; node --test tooling/test/local-plugin.test.mjs tooling/test/project-paths.test.mjs tooling/test/project-scope.test.mjs || failed=1; depcruise --config tooling/dependency-cruiser.mjs plugins/mem0-bridge || failed=1; knip --config tooling/knip.json --tsConfig tooling/tsconfig.json || failed=1; bun audit || failed=1; bun pm pack --dry-run || failed=1; exit \"$failed\"",
    "fix": "failed=0; node tooling/update-direct-deps.mjs --apply || failed=1; bun install || failed=1; knip --config tooling/knip.json --tsConfig tooling/tsconfig.json --fix || failed=1; prettier . --write --config tooling/prettier.json --ignore-path tooling/prettierignore || failed=1; eslint . --config tooling/eslint.config.js --fix || failed=1; bun install || failed=1; bun run check || failed=1; exit \"$failed\""
  },
  "files": [
    "plugins"
  ],
  "dependencies": {
    "@opencode/plugin": "^2.0.29",
    "@opencode/schema": "^2.0.29"
  },
  "devDependencies": {
    "@opencode/cli": "^2.1.4",
    "@types/node": "^26.6.4",
    "dependency-cruiser": "^18.5.0",
    "eslint": "^10.12.0",
    "eslint-config-xo": "^6.0.0",
    "eslint-plugin-boundaries": "^7.2.0",
    "eslint-plugin-sonarjs": "^4.2.2",
    "globals": "^17.13.0",
    "knip": "^6.41.0",
    "prettier": "^3.9.10",
    "typescript": "^6.0.3"
  },
  "overrides": {
    "@opentelemetry/core": "2.8.0",
    "braces": "npm:@dieub/braces-depth-guard@3.0.3-pn.3",
    "handlebars": "4.7.10",
    "katex": "0.18.2",
    "source-map-js": "1.2.2"
  },
  "$schema": "https://json.schemastore.org/package.json",
  "$comment": "The plugin is also available as a local checkout through .opencode/index.ts.",
  "trustedDependencies": [
    "@opencode/cli"
  ]
}
